using System.IO;
namespace Hisab;
public static class CashFlowTests
{
    public static void Run(string directory,List<string> results)
    {
        void Check(bool ok,string name){if(!ok)throw new Exception(name);results.Add("PASS "+name);}
        void Reject(Action action,string name){try{action();}catch(InvalidOperationException){results.Add("PASS "+name);return;}throw new Exception(name);}
        string path=Path.Combine(directory,"cash-flow-"+Guid.NewGuid()+".db");using var s=new Store(path);var a=new AccountingService(s);var day=DateTime.Today.AddDays(-20);long cash=s.AccountId("1101"),equity=s.AccountId("3201"),expense=s.AccountId("5101"),income=s.AccountId("4101");s.SaveAccount(null,"BANK-CF","Bank","Cash");long bank=s.AccountId("BANK-CF");
        long V(FinancialStatement f,string key)=>f.Rows.Single(r=>r.Key==key).Current;
        a.Manual(day.AddDays(-1),"opening cash",[new(cash,100000,0),new(equity,0,100000)]);
        long capital=a.Manual(day,"capital",[new(cash,1000000,0),new(equity,0,1000000)]);long receipt=a.Voucher(true,day,income,cash,200,"income");long payment=a.Voucher(false,day,expense,cash,50,"expense");
        var f=a.CashFlowStatement(day,day);Check(!f.Complete&&V(f,"OpeningCash")==100000&&V(f,"ClosingCash")==1250000&&f.Difference==0,"Cash report ties opening and closing while exposing unclassified movements");
        a.ClassifyCashMovement(capital,cash,1,0,0,1000,0);a.ClassifyCashMovement(receipt,cash,1,200,0,0,0);a.ClassifyCashMovement(payment,cash,-1,50,0,0,0);f=a.CashFlowStatement(day,day);
        Check(f.Complete&&V(f,"OperatingCashIn")==200000&&V(f,"OperatingCashOut")==-50000&&V(f,"FinancingCash")==1000000&&V(f,"NetCashChange")==1150000,"Classified cash receipts and payments reconcile without netting gross flows");
        long transfer=a.Manual(day,"bank transfer",[new(bank,100000,0),new(cash,0,100000)]);f=a.CashFlowStatement(day,day);Check(f.Complete&&V(f,"TransferCashIn")==100000&&V(f,"TransferCashOut")==-100000&&V(f,"NetCashChange")==1150000,"Pure cash transfers are excluded automatically from business activities");
        Reject(()=>a.ClassifyCashMovement(transfer,cash,-1,100,0,0,0),"Automatic pure transfer classification cannot be overridden");
        Reject(()=>a.ClassifyCashMovement(payment,cash,-1,51,0,0,0),"Cash classification cannot exceed movement amount");Reject(()=>a.ClassifyCashMovement(payment,cash,-1,-1,0,0,0),"Cash classification rejects negative allocation");Reject(()=>a.ClassifyCashMovement(payment,cash,-1,1.0001m,0,0,0),"Cash classification enforces JOD precision");
        long mixed=a.Manual(day.AddDays(1),"transfer with fee",[new(bank,100000,0),new(expense,5000,0),new(cash,0,105000)]);a.ClassifyCashMovement(mixed,cash,-1,5,0,0,100);Check(!a.CashFlowStatement(day,day.AddDays(1)).Complete,"Unbalanced transfer split leaves cash report incomplete");a.ClassifyCashMovement(mixed,bank,1,0,0,0,100);f=a.CashFlowStatement(day,day.AddDays(1));Check(f.Complete&&V(f,"OperatingCash")==145000&&V(f,"TransferCash")==0,"Transfer with fee separates operating expense and internal transfer");
        s.SaveAccount(null,"CF-ASSET","Equipment","Asset");long asset=s.AccountId("CF-ASSET");long purchase=a.Manual(day.AddDays(2),"split asset and expense",[new(asset,80000,0),new(expense,20000,0),new(cash,0,100000)]);a.ClassifyCashMovement(purchase,cash,-1,20,80,0,0);f=a.CashFlowStatement(day,day.AddDays(2));Check(f.Complete&&V(f,"InvestingCash")==-80000&&V(f,"OperatingCash")==125000,"One cash payment can split operating and investing activities");
        long noncash=a.Manual(day.AddDays(2),"noncash equipment contribution",[new(asset,50000,0),new(equity,0,50000)]);Check(!a.CashMovements(day,day.AddDays(2)).Any(m=>m.Document==noncash),"Noncash asset contribution is excluded from cash flows");
        a.Reverse(purchase,"reverse split",day.AddDays(3));f=a.CashFlowStatement(day.AddDays(3),day.AddDays(3));Check(f.Complete&&V(f,"OperatingCashIn")==20000&&V(f,"InvestingCashIn")==80000,"Reversal inherits original categories with opposite cash direction");Check(V(a.CashFlowStatement(day,day.AddDays(2)),"InvestingCash")==-80000,"Later reversal preserves earlier cash report cutoff");
        a.ClassifyCashMovement(receipt,cash,1,150,0,0,0);Check(!a.CashFlowStatement(day,day).Complete&&V(a.CashFlowStatement(day,day),"UnclassifiedCashIn")==50000,"Partial classification exposes exact unclassified remainder");a.ClassifyCashMovement(receipt,cash,1,200,0,0,0);
        long prior=a.Voucher(true,day.AddYears(-1),income,cash,30,"prior receipt");a.ClassifyCashMovement(prior,cash,1,30,0,0,0);Check(a.CashFlowStatement(day,day).Rows.Single(r=>r.Key=="OperatingCashIn").Prior==30000,"Cash report compares same period one year earlier");
        long before=s.Balance(cash);a.ClassifyCashMovement(payment,cash,-1,25,25,0,0);Check(s.Balance(cash)==before,"Cash classification changes presentation without posting entries");
        // Simulate changed imported entry data: an old allocation must never silently carry forward.
        s.Exec("UPDATE entries SET debit=debit*2,credit=credit*2 WHERE doc=@p0",payment);var stale=a.CashMovements(day,day).Single(m=>m.Document==payment);Check(stale.Stale&&stale.Unclassified==100000&&!a.CashFlowStatement(day,day).Complete,"Changed cash amount invalidates stale saved classification");
        using var reopened=new Store(path);Check(new AccountingService(reopened).CashMovements(day,day).Single(m=>m.Document==capital).Financing==1000000,"Cash classification survives database reopen");
        Reject(()=>a.CashFlowStatement(day,day.AddDays(-1)),"Cash report rejects reversed date range");
        long chequeDoc=a.RegisterCheque(true,"CF-1","Bank",income,40,day.AddDays(4),day.AddDays(4));Check(a.CashMovements(day.AddDays(4),day.AddDays(4)).Count==0,"Pending cheque registration does not count as cash received");
        long cheque=Convert.ToInt64(s.Scalar("SELECT id FROM cheques WHERE issue_doc=@p0",chequeDoc));long cleared=a.SettleCheque(cheque,"Cleared",bank,day.AddDays(5),"cleared");a.ClassifyCashMovement(cleared,bank,1,40,0,0,0);Check(V(a.CashFlowStatement(day.AddDays(5),day.AddDays(5)),"OperatingCashIn")==40000,"Cheque clearing enters cash flow on settlement date");
        a.SettleCheque(cheque,"Bounced",bank,day.AddDays(6),"returned");Check(V(a.CashFlowStatement(day.AddDays(6),day.AddDays(6)),"OperatingCashOut")==-40000,"Bounced cleared cheque reverses cash under inherited category");
        a.Voucher(true,day.AddDays(7),income,cash,10,"unknown receipt");a.Voucher(false,day.AddDays(7),expense,cash,10,"unknown payment");f=a.CashFlowStatement(day.AddDays(7),day.AddDays(7));Check(!f.Complete&&V(f,"UnclassifiedCash")==0&&V(f,"UnclassifiedCashIn")==10000,"Offsetting unclassified flows cannot hide behind a zero net balance");
        long reversal=Convert.ToInt64(s.Scalar("SELECT id FROM documents WHERE original=@p0 AND kind='RV'",purchase));a.ClassifyCashMovement(reversal,cash,1,0,0,100,0);Check(V(a.CashFlowStatement(day.AddDays(3),day.AddDays(3)),"FinancingCashIn")==100000&&V(a.CashFlowStatement(day,day.AddDays(2)),"InvestingCash")==-80000,"Explicit reversal classification overrides inheritance without changing original");
        long both=a.Manual(day.AddDays(8),"both cash directions",[new(cash,1000,0),new(expense,1000,0),new(cash,0,1000),new(income,0,1000)]);a.ClassifyCashMovement(both,cash,1,1,0,0,0);a.ClassifyCashMovement(both,cash,-1,1,0,0,0);f=a.CashFlowStatement(day.AddDays(8),day.AddDays(8));Check(f.Complete&&V(f,"OperatingCashIn")==1000&&V(f,"OperatingCashOut")==-1000,"Same cash account preserves both directions in a mixed journal");
        long badIn=a.Voucher(true,day.AddDays(9),income,cash,1,"wrong transfer in"),badOut=a.Voucher(false,day.AddDays(9),expense,cash,1,"wrong transfer out");a.ClassifyCashMovement(badIn,cash,1,0,0,0,1);a.ClassifyCashMovement(badOut,cash,-1,0,0,0,1);f=a.CashFlowStatement(day.AddDays(9),day.AddDays(9));Check(!f.Complete&&V(f,"TransferCash")==0,"Opposing transfer errors in different documents still flag incomplete report");
        s.SaveUser("cash-viewer","TestPassword123","Viewer");s.Login("cash-viewer","TestPassword123");Reject(()=>a.ClassifyCashMovement(capital,cash,1,0,0,1000,0),"Viewer cannot change cash-flow classifications");Check(a.CashFlowStatement(day,day).Rows.Count>0,"Viewer can read cash-flow report");
    }
}
